            boundaryTraversal.push_back(root->data);
        }

        if(root->left != nullptr){
            addLeftBoundaryTraversal(root->left,boundaryTraversal);
        }
        else if(root->right != nullptr){
            addLeftBoundaryTraversal(root->right,boundaryTraversal);
        }


    }

    void addLeaves(TreeNode* root, vector<int>&boundaryTraversal)
    {
        if(root == nullptr){
            return ;
        }

        addLeaves(root->left,boundaryTraversal);
        addLeaves(root->right,boundaryTraversal);

        if(isLeaf(root)){
            boundaryTraversal.push_back(root->data);
        }
    }

    void addRightBoundaryTraversal(TreeNode* root, vector<int>&rightBoundaryElements)
    {
        if(root == nullptr){
            return ;
        }

        if(!isLeaf(root)){
            rightBoundaryElements.push_back(root->data);
        }

        if(root->right != nullptr){
            addRightBoundaryTraversal(root->right,rightBoundaryElements);
        }
        else if(root->left != nullptr){
            addRightBoundaryTraversal(root->left,rightBoundaryElements);
        }

    }

public:
