 * };
 **/

class Solution{
public:
    void dfsl(TreeNode* root,vector<int>&ans,int& right){
        if(!root){
            return;
        }
        if(right == 0 || (root->left == nullptr && root->right == nullptr)){
            ans.push_back(root->data);
        }
        if(root->left == nullptr && root->right == nullptr){
            right++;
        }
        dfsl(root->left,ans,right);
        dfsl(root->right,ans,right);
    }

    void dfsr(TreeNode* root,vector<int>&ans,int& right){
        if(!root){
            return;
        }
        if(right == 0 || (root->left == nullptr && root->right == nullptr)){
            ans.push_back(root->data);
        }
        if(root->left == nullptr && root->right == nullptr){
            right++;
        }
        dfsr(root->right,ans,right);
        dfsr(root->left,ans,right);
    }
public:
    vector <int> boundary(TreeNode* root){
    	//your code goes here
        vector<int>ans;
        int right = 0;
        if(!root) return ans;
        ans.push_back(root->data);
        dfsl(root->left,ans,right);
        right = 0;
        vector<int>res;
        dfsr(root->right,res,right);
        reverse(res.begin(),res.end());
        for(int i = 0; i < res.size(); i++){
            ans.push_back(res[i]);
        }
        return ans;
    }
};
